#include <vector>

typedef float rational_t;
typedef float time_value_t;

class stringx
{
  char *characters;
  void *buffer;

public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  stringx &operator=(const stringx &);
};

extern const stringx empty_string;

class widget
{
  char data[0x140];

public:
  virtual ~widget();
};

class bitmap_widget;

class timer_widget : public widget
{
protected:
  class timer_func
  {
  public:
    time_value_t time;
    stringx function;

    timer_func()
    {
      time = -1.0f;
      function = empty_string;
    }

    timer_func(const timer_func &b)
    {
      copy(b);
    }

    ~timer_func()
    {
    }

    void copy(const timer_func &b)
    {
      time = b.time;
      function = b.function;
    }

    timer_func &operator=(const timer_func &b)
    {
      copy(b);
      return *this;
    }
  };

  bitmap_widget *digits[10];
  bitmap_widget *colon1;
  bitmap_widget *colon2;
  bitmap_widget *point;
  bitmap_widget *bg;
  int minutes;
  int seconds1;
  int seconds2;
  int tenths;
  rational_t time_left;
  bool running;
  bool updated;
  vector<timer_func> script_calls_left;
  vector<timer_func> script_calls_made;

public:
  virtual ~timer_widget();
};

timer_widget::~timer_widget()
{
  script_calls_left.resize(0);
  script_calls_made.resize(0);
}
